from __future__ import annotations

from pathlib import Path

from docx import Document


DOC = Path("D:/work/project/coal-regulation-ai") / "\u7814\u7535\u8d5b\u6280\u672f\u8bba\u6587\u6700\u7ec8\u7248v4.docx"

OLD = "\u7ecf\u9a8c\u673a\u5236\u5206\u4e3a\u9884\u7f6e\u7ecf\u9a8c\u3001\u8fd0\u884c\u7ecf\u9a8c\u548c\u53cd\u9988\u7ecf\u9a8c\u4e09\u7ea7\u3002\u9884\u7f6e\u7ecf\u9a8c\u5305\u62ec\u8d5b\u524d\u4eba\u5de5\u7f16\u5199\u7684 Prompt \u6a21\u677f\u3001Skill \u6d41\u7a0b\u3001\u5ba1\u67e5\u89c4\u5219\u548c\u5de5\u5177\u8c03\u7528\u89c4\u8303\uff0c\u5b83\u4eec\u662f\u7cfb\u7edf\u521d\u59cb\u80fd\u529b\uff0c\u4e0d\u7531\u6570\u636e\u98de\u8f6e\u81ea\u52a8\u751f\u6210\uff1b\u8fd0\u884c\u7ecf\u9a8c\u4fdd\u5b58\u4e3b\u667a\u80fd\u4f53\u7684\u4efb\u52a1\u5224\u65ad\u3001\u8bc1\u636e\u9009\u62e9\u3001\u5de5\u5177\u8c03\u7528\u548c\u51b2\u7a81\u88c1\u51b3\u8fc7\u7a0b\uff0c\u7528\u4e8e\u8ffd\u6eaf\u3001\u8bc4\u6d4b\u548c\u6392\u9519\uff1b\u53cd\u9988\u7ecf\u9a8c\u6765\u81ea\u5ba1\u67e5\u4eba\u5458\u7684\u63a5\u53d7\u3001\u9a73\u56de\u3001\u4fee\u6539\u3001\u8865\u5145\u8bc1\u636e\u548c\u73b0\u573a\u5904\u7f6e\u786e\u8ba4\u3002\u6570\u636e\u98de\u8f6e\u53ea\u56f4\u7ed5\u4eba\u5de5\u53cd\u9988\u95ed\u73af\u5f00\u5c55\uff1a\u7cfb\u7edf\u5c06\u53cd\u9988\u8bb0\u5f55\u6c89\u6dc0\u4e3a\u8bc4\u6d4b\u6837\u672c\u3001\u95ee\u9898\u5206\u5e03\u7edf\u8ba1\u548c\u4eba\u5de5\u7ef4\u62a4\u9884\u7f6e Prompt/Skill \u7684\u4f9d\u636e\uff0c\u4f46\u4e0d\u81ea\u52a8\u751f\u6210\u6216\u66ff\u6362 Prompt/Skill\u3002"

NEW = "\u7ecf\u9a8c\u673a\u5236\u5206\u4e3a\u9884\u7f6e\u7ecf\u9a8c\u3001\u8fd0\u884c\u7ecf\u9a8c\u548c\u53cd\u9988\u7ecf\u9a8c\u4e09\u7ea7\u3002\u9884\u7f6e\u7ecf\u9a8c\u5305\u62ec\u8d5b\u524d\u4eba\u5de5\u7f16\u5199\u7684 Prompt \u6a21\u677f\u3001Skill \u6d41\u7a0b\u3001\u5ba1\u67e5\u89c4\u5219\u548c\u5de5\u5177\u8c03\u7528\u89c4\u8303\uff0c\u5b83\u4eec\u662f\u7cfb\u7edf\u521d\u59cb\u80fd\u529b\uff0c\u4e0d\u7531\u6570\u636e\u98de\u8f6e\u81ea\u52a8\u751f\u6210\uff1b\u8fd0\u884c\u7ecf\u9a8c\u4fdd\u5b58\u4e3b\u667a\u80fd\u4f53\u7684\u4efb\u52a1\u5224\u65ad\u3001\u8bc1\u636e\u9009\u62e9\u3001\u5de5\u5177\u8c03\u7528\u548c\u51b2\u7a81\u88c1\u51b3\u8fc7\u7a0b\uff0c\u7528\u4e8e\u8ffd\u6eaf\u3001\u8bc4\u6d4b\u548c\u6392\u9519\uff1b\u53cd\u9988\u7ecf\u9a8c\u6765\u81ea\u5ba1\u67e5\u4eba\u5458\u7684\u63a5\u53d7\u3001\u9a73\u56de\u3001\u4fee\u6539\u3001\u8865\u5145\u8bc1\u636e\u548c\u73b0\u573a\u5904\u7f6e\u786e\u8ba4\u3002\u6570\u636e\u98de\u8f6e\u53ea\u4e0e\u53cd\u9988\u7ecf\u9a8c\u5173\u8054\uff1a\u7cfb\u7edf\u5c06\u4eba\u5de5\u53cd\u9988\u6c89\u6dc0\u4e3a\u8bc4\u6d4b\u6837\u672c\u548c\u95ee\u9898\u5206\u5e03\u7edf\u8ba1\uff1b\u82e5\u540e\u7eed\u9700\u8981\u8c03\u6574\u9884\u7f6e Prompt \u6216 Skill\uff0c\u5219\u5c5e\u4e8e\u4eba\u5de5\u7248\u672c\u7ef4\u62a4\u6d41\u7a0b\uff0c\u4e0d\u5c5e\u4e8e\u98de\u8f6e\u81ea\u52a8\u751f\u6210\u6216\u81ea\u52a8\u66ff\u6362\u8303\u56f4\u3002"


def main() -> None:
    doc = Document(str(DOC))
    changed = 0
    for p in doc.paragraphs:
        if p.text == OLD:
            p.runs[0].text = NEW
            for run in p.runs[1:]:
                run.text = ""
            changed += 1
    if changed != 1:
        raise RuntimeError(f"expected one replacement, got {changed}")
    doc.save(str(DOC))
    print(f"changed={changed}")


if __name__ == "__main__":
    main()
